const upsertWorkflowDirectoryRef = `-- name: UpsertWorkflowDirectoryRef :exec
INSERT INTO workflow.directory_ref (
    kind, id, name, name_ar, email, parent_id, metadata, updated_at
) VALUES (
    $1, $2, $3, $4, $5, $6, $7, now()
) ON CONFLICT (kind, id) DO UPDATE SET
    name = EXCLUDED.name,
    name_ar = EXCLUDED.name_ar,
    email = EXCLUDED.email,
    parent_id = EXCLUDED.parent_id,
    metadata = EXCLUDED.metadata,
    updated_at = now()
`

type UpsertWorkflowDirectoryRefParams struct {
	Kind     string          `json:"kind"`
	ID       string          `json:"id"`
	Name     string          `json:"name"`
	NameAr   *string         `json:"nameAr"`
	Email    *string         `json:"email"`
	ParentID *string         `json:"parentId"`
	Metadata json.RawMessage `json:"metadata"`
}

func (q *Queries) UpsertWorkflowDirectoryRef(ctx context.Context, arg UpsertWorkflowDirectoryRefParams) error {
	_, err := q.db.Exec(ctx, upsertWorkflowDirectoryRef,
		arg.Kind,
		arg.ID,
		arg.Name,
		arg.NameAr,
		arg.Email,
		arg.ParentID,
		arg.Metadata,
	)
	return err
}
